// AppDataGrid.tsx
// Generated by CodeCreator - Reusable DataGrid wrapper with export, filters, column visibility
import { useState, useMemo, useCallback, useRef, useEffect, type ReactNode } from 'react';
import ExcelJS from 'exceljs';
import {
  DataGrid,
  type GridColDef,
  type GridPaginationModel,
  type GridSortModel,
  type GridFilterModel,
  type GridColumnVisibilityModel,
  type GridRowSelectionModel,
  GridToolbarContainer,
  GridToolbarColumnsButton,
  GridToolbarFilterButton,
  GridToolbarDensitySelector,
  useGridApiRef,
} from '@mui/x-data-grid';
import {
  Box, TextField, Typography, IconButton, Tooltip, InputAdornment,
  Chip, Button, Menu, MenuItem, ListItemIcon, ListItemText,
  Divider, Select, FormControl, InputLabel, Dialog, DialogTitle, DialogContent, DialogActions,
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import FileDownloadIcon from '@mui/icons-material/FileDownload';
import TableChartIcon from '@mui/icons-material/TableChart';
import DescriptionIcon from '@mui/icons-material/Description';
import ClearIcon from '@mui/icons-material/Clear';
import FitScreenIcon from '@mui/icons-material/FitScreen';
import InboxIcon from '@mui/icons-material/Inbox';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import { localizeColumns } from '../../i18n/localizeColumns';
import he from '../../i18n/he';

interface AppDataGridProps {
  rows: unknown[];
  columns: GridColDef[];
  loading?: boolean;
  title?: string;
  entityName?: string; // Used as localStorage key for state persistence
  getRowId?: (row: unknown) => string | number;
  onRowClick?: (id: string | number) => void;
  onSelectionChange?: (ids: (string | number)[]) => void;
  showSearch?: boolean;
  showExport?: boolean;
  showToolbar?: boolean;
  checkboxSelection?: boolean;
  headerActions?: ReactNode;
  initialPageSize?: number;
  initialColumnVisibility?: GridColumnVisibilityModel;
  // Server-side pagination props
  rowCount?: number;
  paginationModel?: GridPaginationModel;
  onPaginationModelChange?: (model: GridPaginationModel) => void;
  serverSearch?: string;
  onServerSearchChange?: (search: string) => void;
  // Server-side sorting props
  sortModel?: GridSortModel;
  onSortModelChange?: (model: GridSortModel) => void;
  // Context menu
  onContextMenuActions?: (id: string | number, row: unknown) => { label: string; icon?: ReactNode; onClick: () => void; divider?: boolean }[];
  // Empty state
  onCreateNew?: () => void;
  // Inline editing
  editable?: boolean;
  processRowUpdate?: (newRow: unknown, oldRow: unknown) => Promise<unknown>;
  // Bulk edit
  onBulkEdit?: (ids: (string | number)[], field: string, value: unknown) => Promise<void>;
  bulkEditableFields?: { field: string; label: string; type: string }[];
}

function escapeCsvValue(val: unknown): string {
  const str = String(val ?? '');
  if (str.includes(',') || str.includes('"') || str.includes('\n'))
    return `"${str.replace(/\"/g, '""')}"`;
  return str;
}

function TooltipCell({ value }: { value: unknown }) {
  const cellRef = useRef<HTMLDivElement>(null);
  const [isOverflowed, setIsOverflowed] = useState(false);

  useEffect(() => {
    const el = cellRef.current;
    if (el) setIsOverflowed(el.scrollWidth > el.clientWidth);
  }, [value]);

  return (
    <Tooltip title={isOverflowed ? String(value ?? '') : ''} enterDelay={500} disableHoverListener={!isOverflowed}>
      <Box ref={cellRef} sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
        {String(value ?? '')}
      </Box>
    </Tooltip>
  );
}

function addTooltipToColumns(cols: GridColDef[]): GridColDef[] {
  return cols.map((col) => {
    if (col.type === 'actions' || col.renderCell) return col;
    return { ...col, renderCell: (params) => <TooltipCell value={params.value} /> } as GridColDef;
  });
}

function NoRowsOverlay({ onCreateClick }: { onCreateClick?: () => void }) {
  return (
    <Box display="flex" flexDirection="column" alignItems="center" justifyContent="center" height="100%" gap={1} p={4}>
      <InboxIcon sx={{ fontSize: 64, color: 'text.disabled' }} />
      <Typography variant="h6" color="text.secondary">No records found</Typography>
      <Typography variant="body2" color="text.secondary">Try adjusting your search or filters</Typography>
      {onCreateClick && (
        <Button variant="contained" size="small" onClick={onCreateClick} sx={{ mt: 1 }}>
          Create New
        </Button>
      )}
    </Box>
  );
}

function BulkEditDialog({
  open,
  onClose,
  fields,
  onApply,
}: {
  open: boolean;
  onClose: () => void;
  fields: { field: string; label: string; type: string }[];
  onApply: (field: string, value: unknown) => void;
}) {
  const [selectedField, setSelectedField] = useState('');
  const [fieldValue, setFieldValue] = useState<string>('');

  const currentField = fields.find((f) => f.field === selectedField);
  const inputType = currentField?.type === 'number' ? 'number' : currentField?.type === 'date' ? 'date' : 'text';

  const handleApply = () => {
    if (!selectedField) return;
    const parsed = inputType === 'number' ? Number(fieldValue) : fieldValue;
    onApply(selectedField, parsed);
    setSelectedField('');
    setFieldValue('');
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Bulk Edit</DialogTitle>
      <DialogContent sx={{ display: 'flex', flexDirection: 'column', gap: 2, pt: 2 }}>
        <FormControl fullWidth size="small" sx={{ mt: 1 }}>
          <InputLabel>Field</InputLabel>
          <Select value={selectedField} label="Field" onChange={(e) => { setSelectedField(e.target.value); setFieldValue(''); }}>
            {fields.map((f) => (
              <MenuItem key={f.field} value={f.field}>{f.label}</MenuItem>
            ))}
          </Select>
        </FormControl>
        {selectedField && (
          <TextField
            label="Value"
            type={inputType}
            value={fieldValue}
            onChange={(e) => setFieldValue(e.target.value)}
            fullWidth
            size="small"
            slotProps={{ inputLabel: { shrink: true } }}
          />
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button variant="contained" onClick={handleApply} disabled={!selectedField}>Apply</Button>
      </DialogActions>
    </Dialog>
  );
}

function CustomToolbar({ onClearFilters, onAutoSize }: { onClearFilters: () => void; onAutoSize: () => void }) {
  return (
    <GridToolbarContainer>
      <GridToolbarColumnsButton />
      <GridToolbarFilterButton />
      <GridToolbarDensitySelector />
      <Button size="small" startIcon={<FitScreenIcon />} onClick={onAutoSize}>
        Auto-size
      </Button>
      <Button size="small" startIcon={<ClearIcon />} onClick={onClearFilters}>
        Clear Filters
      </Button>
    </GridToolbarContainer>
  );
}

export default function AppDataGrid({
  rows,
  columns: rawColumns,
  loading = false,
  title: rawTitle,
  entityName,
  getRowId,
  onRowClick,
  onSelectionChange,
  showSearch = true,
  showExport = true,
  showToolbar = true,
  checkboxSelection = false,
  headerActions,
  initialPageSize = 25,
  initialColumnVisibility = {},
  rowCount,
  paginationModel: externalPaginationModel,
  onPaginationModelChange: externalOnPaginationModelChange,
  serverSearch,
  onServerSearchChange,
  sortModel: externalSortModel,
  onSortModelChange: externalOnSortModelChange,
  onContextMenuActions,
  onCreateNew,
  editable = false,
  processRowUpdate,
  onBulkEdit,
  bulkEditableFields = [],
}: AppDataGridProps) {
  const apiRef = useGridApiRef();
  const storageKey = entityName ? `datagrid_${entityName}` : null;

  // Shadowing the raw props on purpose. Every consumer below — the grid, the
  // CSV export, the Excel export, the heading — then reads the localized
  // version without a separate edit at each site, so no site can be missed.
  const columns = useMemo(() => localizeColumns(rawColumns), [rawColumns]);
  const title = useMemo(() => {
    if (rawTitle) return rawTitle;
    if (!entityName) return undefined;
    return he.entities[entityName as keyof typeof he.entities]?.p;
  }, [rawTitle, entityName]);

  // Load saved state from localStorage
  const savedState = useMemo(() => {
    if (!storageKey) return null;
    try { return JSON.parse(localStorage.getItem(storageKey) || 'null'); } catch { return null; }
  }, [storageKey]);

  const isServerMode = rowCount !== undefined;
  const [localSearch, setLocalSearch] = useState('');
  const [searchInput, setSearchInput] = useState(serverSearch ?? savedState?.searchInput ?? '');
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();
  const search = isServerMode ? (serverSearch ?? '') : localSearch;
  const setSearch = isServerMode ? (onServerSearchChange ?? (() => {})) : setLocalSearch;
  const handleSearchInput = useCallback((value: string) => {
    setSearchInput(value);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => setSearch(value), isServerMode ? 400 : 0);
  }, [setSearch, isServerMode]);
  useEffect(() => { return () => { if (debounceRef.current) clearTimeout(debounceRef.current); }; }, []);
  const [localPaginationModel, setLocalPaginationModel] = useState<GridPaginationModel>({
    pageSize: savedState?.pageSize ?? initialPageSize,
    page: 0,
  });
  const activePaginationModel = externalPaginationModel ?? localPaginationModel;
  const setActivePaginationModel = externalOnPaginationModelChange ?? setLocalPaginationModel;
  const [filterModel, setFilterModel] = useState<GridFilterModel>(savedState?.filterModel ?? { items: [] });
  const [columnVisibilityModel, setColumnVisibilityModel] =
    useState<GridColumnVisibilityModel>(savedState?.columnVisibility ?? initialColumnVisibility);
  const [exportMenuAnchor, setExportMenuAnchor] = useState<HTMLElement | null>(null);
  const [contextMenu, setContextMenu] = useState<{ mouseX: number; mouseY: number; rowId: string | number; row: unknown } | null>(null);
  const [bulkEditOpen, setBulkEditOpen] = useState(false);
  const [selectionModel, setSelectionModel] = useState<(string | number)[]>([]);

  const handleContextMenu = useCallback((event: React.MouseEvent) => {
    if (!onContextMenuActions) return;
    event.preventDefault();
    const rowEl = (event.target as HTMLElement).closest('[data-id]');
    if (!rowEl) return;
    const rowId = rowEl.getAttribute('data-id') ?? '';
    const row = rows.find((r) => String(getRowId ? getRowId(r) : (r as any).id) === rowId);
    setContextMenu({ mouseX: event.clientX, mouseY: event.clientY, rowId, row });
  }, [onContextMenuActions, rows, getRowId]);

  // Persist DataGrid state to localStorage
  useEffect(() => {
    if (!storageKey) return;
    const state = {
      columnVisibility: columnVisibilityModel,
      pageSize: activePaginationModel.pageSize,
      filterModel,
      searchInput,
    };
    localStorage.setItem(storageKey, JSON.stringify(state));
  }, [storageKey, columnVisibilityModel, activePaginationModel.pageSize, filterModel, searchInput]);

  const filteredRows = useMemo(() => {
    if (isServerMode || !search) return rows;
    const lowerSearch = search.toLowerCase();
    return rows.filter((row: unknown) =>
      Object.values(row as any).some((val: any) =>
        String(val).toLowerCase().includes(lowerSearch)
      )
    );
  }, [rows, search, isServerMode]);

  const handleClearFilters = useCallback(() => {
    setSearch('');
    setFilterModel({ items: [] });
  }, []);

  const handleAutoSize = useCallback(() => {
    if (apiRef.current) {
      apiRef.current.autosizeColumns({
        includeHeaders: true,
        includeOutliers: false,
        expand: true,
      });
    }
  }, [apiRef]);

  const handleExportCSV = useCallback(() => {
    const visibleCols = apiRef.current
      ? apiRef.current.getVisibleColumns().filter(c => c.field !== 'actions')
      : columns.filter(c => columnVisibilityModel[c.field] !== false && c.field !== 'actions');
    const headers = visibleCols.map((c) => c.headerName || c.field).join(',');
    const csvRows = filteredRows.map((row) =>
      visibleCols.map((c) => escapeCsvValue((row as any)[c.field])).join(',')
    );
    const csv = [headers, ...csvRows].join('\n');
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${title || 'export'}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    setExportMenuAnchor(null);
  }, [apiRef, columns, filteredRows, title, columnVisibilityModel]);

  const handleExportExcel = useCallback(async () => {
    const visibleRows = filteredRows || [];
    if (visibleRows.length === 0) { alert('No data to export'); return; }

    // Get visible columns from DataGrid (respects column visibility)
    const visibleColumns = apiRef.current
      ? apiRef.current.getVisibleColumns().map(col => col.field).filter(field => field !== 'actions')
      : Object.keys(visibleRows[0] as any || {});

    // Filter data to only include visible columns
    const exportData = visibleRows.map(row => {
      const filteredRow: any = {};
      const rowAny = row as any;
      visibleColumns.forEach(col => {
        if (col in rowAny) filteredRow[col] = rowAny[col];
      });
      return filteredRow;
    });

    // Create workbook and worksheet
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet(title || 'Data');

    // Get column names from first row (only visible columns)
    const columnNames = exportData.length > 0 ? Object.keys(exportData[0]) : [];
    worksheet.columns = columnNames.map(name => ({ header: name, key: name, width: 15 }));

    // Add data rows
    exportData.forEach(row => worksheet.addRow(row));

    // Style header row
    const headerRow = worksheet.getRow(1);
    headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
    headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF4472C4' } };
    headerRow.alignment = { horizontal: 'center', vertical: 'middle' };
    headerRow.height = 20;

    // Auto-fit columns based on content
    worksheet.columns.forEach(column => {
      let maxLength = column.header?.length || 10;
      column.eachCell?.({ includeEmpty: false }, cell => {
        const cellLength = cell.value ? String(cell.value).length : 0;
        maxLength = Math.max(maxLength, cellLength);
      });
      column.width = Math.min(maxLength + 2, 50);
    });

    // Freeze header row
    worksheet.views = [{ state: 'frozen', ySplit: 1 }];

    // Generate Excel file and download
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${title || 'export'}_${new Date().toISOString().split('T')[0]}.xlsx`;
    link.click();
    window.URL.revokeObjectURL(url);
    setExportMenuAnchor(null);
  }, [apiRef, filteredRows, title]);

  return (
    <Box>
      {/* Header bar - stays outside horizontal scroll */}
      <Box display="flex" flexWrap="wrap" alignItems="center" gap={1} mb={2}>
        {title && <Typography variant="h5" sx={{ mr: 1 }}>{title}</Typography>}
        <Chip label={`${isServerMode ? rowCount : filteredRows.length} rows`} size="small" variant="outlined" />
        {showSearch && (
          <TextField
            size="small"
            placeholder="Search..."
            value={searchInput}
            onChange={(e) => handleSearchInput(e.target.value)}
            slotProps={{
              input: {
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon fontSize="small" />
                  </InputAdornment>
                ),
              },
            }}
            sx={{ minWidth: 220 }}
          />
        )}
        {showExport && (
          <>
            <Tooltip title="Export">
              <IconButton onClick={(e) => setExportMenuAnchor(e.currentTarget)} size="small">
                <FileDownloadIcon />
              </IconButton>
            </Tooltip>
            <Menu
              anchorEl={exportMenuAnchor}
              open={Boolean(exportMenuAnchor)}
              onClose={() => setExportMenuAnchor(null)}
            >
              <MenuItem onClick={handleExportCSV}>
                <ListItemIcon><DescriptionIcon fontSize="small" /></ListItemIcon>
                <ListItemText>Export CSV</ListItemText>
              </MenuItem>
              <MenuItem onClick={handleExportExcel}>
                <ListItemIcon><TableChartIcon fontSize="small" /></ListItemIcon>
                <ListItemText>Export Excel</ListItemText>
              </MenuItem>
            </Menu>
          </>
        )}
        {headerActions}
        {onBulkEdit && selectionModel.length > 0 && (
          <Button size="small" variant="outlined" startIcon={<EditIcon />} onClick={() => setBulkEditOpen(true)}>
            Bulk Edit ({selectionModel.length})
          </Button>
        )}
      </Box>

      {/* DataGrid with built-in toolbar for columns, filters, density */}
      <DataGrid
        apiRef={apiRef}
        rows={filteredRows}
        columns={editable ? columns : addTooltipToColumns(columns)}
        loading={loading}
        getRowId={getRowId}
        paginationModel={activePaginationModel}
        onPaginationModelChange={setActivePaginationModel}
        pageSizeOptions={[5, 10, 25, 50, 100]}
        paginationMode={isServerMode ? 'server' : 'client'}
        rowCount={isServerMode ? rowCount : undefined}
        sortingMode={isServerMode ? 'server' : 'client'}
        sortModel={externalSortModel}
        onSortModelChange={externalOnSortModelChange}
        filterModel={filterModel}
        onFilterModelChange={setFilterModel}
        columnVisibilityModel={columnVisibilityModel}
        onColumnVisibilityModelChange={setColumnVisibilityModel}
        sx={{ '& .MuiDataGrid-columnHeaders': { position: 'sticky', top: 0, zIndex: 1 } }}
        slots={{
          ...(showToolbar ? { toolbar: () => <CustomToolbar onClearFilters={handleClearFilters} onAutoSize={handleAutoSize} /> } : {}),
          noRowsOverlay: NoRowsOverlay as any,
        }}
        slotProps={{
          noRowsOverlay: { onCreateClick: onCreateNew } as never,
          row: onContextMenuActions ? { onContextMenu: handleContextMenu } as never : undefined,
        }}
        onRowClick={onRowClick ? (params) => onRowClick(params.id) : undefined}
        checkboxSelection={checkboxSelection}
        disableRowSelectionOnClick
        onRowSelectionModelChange={(model: GridRowSelectionModel) => {
          const ids = model as (string | number)[];
          setSelectionModel(ids);
          onSelectionChange?.(ids);
        }}
        {...(editable ? { editMode: 'row', processRowUpdate } : {})}
      />

      {/* Context Menu */}
      {contextMenu && onContextMenuActions && (
        <Menu
          open={Boolean(contextMenu)}
          onClose={() => setContextMenu(null)}
          anchorReference="anchorPosition"
          anchorPosition={contextMenu ? { top: contextMenu.mouseY, left: contextMenu.mouseX } : undefined}
        >
          {onContextMenuActions(contextMenu.rowId, contextMenu.row).map((action, idx) => [
            action.divider && <Divider key={`div-${idx}`} />,
            <MenuItem key={idx} onClick={() => { action.onClick(); setContextMenu(null); }}>
              {action.icon && <ListItemIcon>{action.icon}</ListItemIcon>}
              <ListItemText>{action.label}</ListItemText>
            </MenuItem>,
          ])}
        </Menu>
      )}

      {/* Bulk Edit Dialog */}
      {onBulkEdit && (
        <BulkEditDialog
          open={bulkEditOpen}
          onClose={() => setBulkEditOpen(false)}
          fields={bulkEditableFields}
          onApply={(field, value) => onBulkEdit(selectionModel, field, value)}
        />
      )}
    </Box>
  );
}

